package project;

/** Scalable administration dashboard with paged users, posts, and reports. */
final class AdminDashboardPage {
    private AdminDashboardPage() {}

    static String render() {
        return "<!doctype html><html lang='ko'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>관리자 | CINEHUB</title>"
            + "<link rel='stylesheet' href='/static/assets/css/style.css'><link rel='stylesheet' href='/static/assets/css/widgets.css'><link rel='stylesheet' href='/static/assets/css/responsive.css'></head><body>"
            + "<header class='main-header header-style-1'><div class='header-top'></div><div class='header-sticky'><div class='container align-self-center'><div class='main-nav'><nav><ul class='main-menu'><li><a href='/'>홈</a></li><li><a href='/movies'>영화 추천</a></li><li><a href='/posts'>게시글</a></li><li><a href='/admin'>관리자</a></li></ul></nav></div></div></div></header>"
            + "<main><div class='container admin-dashboard'><section class='hero admin-hero'><span class='muted'>ADMIN</span><h1>관리자 대시보드</h1><div id='stats'>통계를 불러오는 중입니다.</div><p><a class='btn-main' href='/admin/logs'>관리 로그 보기</a></p></section>"
            + "<section class='admin-section'><h2>회원 관리</h2><div class='admin-search'><input id='userQuery' placeholder='닉네임 또는 아이디 검색'><button id='userSearch'>검색</button></div><div id='users'></div><nav class='pagination' id='userPaging'></nav></section>"
            + "<section class='admin-section'><h2>게시글 관리</h2><div class='admin-search'><input id='postQuery' placeholder='게시글 제목 또는 작성자 검색'><button id='postSearch'>검색</button></div><div id='adminPosts'></div><nav class='pagination' id='postPaging'></nav></section>"
            + "<section class='admin-section'><h2>신고 관리</h2><div class='admin-search'><input id='reportQuery' placeholder='신고 사유, 신고자, 유형 검색'><button id='reportSearch'>검색</button></div><div id='reports'></div><nav class='pagination' id='reportPaging'></nav></section></div></main><footer class='main-footer'><div class='container'><p class='text-center text-muted'>CINEHUB · 영화 탐색 커뮤니티</p></div></footer>"
            + "<script>function safe(v){var d=document.createElement('div');d.textContent=v||'';return d.innerHTML;}function csrf(){var m=document.cookie.match(/(?:^|; )CINEHUB_CSRF=([^;]+)/);return m?decodeURIComponent(m[1]):'';}function controls(id,page,pages,click){document.getElementById(id).innerHTML=Array.from({length:pages},function(_,i){return '<button class=\"page-number '+(page===i?'active':'')+'\">'+(i+1)+'</button>';}).join('');Array.prototype.forEach.call(document.querySelectorAll('#'+id+' button'),function(b,i){b.onclick=function(){click(i);};});}function loadStats(){fetch('/api/admin/stats').then(function(r){return r.json();}).then(function(s){document.getElementById('stats').textContent='게시글 '+s.posts+' · 댓글 '+s.comments+' · 회원 '+s.users+' · 미처리 신고 '+s.pendingReports;});}var userPage=0;function loadUsers(){var q=document.getElementById('userQuery').value.trim();fetch('/api/admin/users?limit=10&offset='+(userPage*10)+'&q='+encodeURIComponent(q)).then(function(r){return r.json();}).then(function(d){document.getElementById('users').innerHTML=(d.users||[]).map(function(u){var next=u.status==='SUSPENDED'?'ACTIVE':'SUSPENDED';return '<div class=\"post-card admin-user-row\"><b>'+safe(u.nickname)+'</b><span>'+safe(u.loginId)+' · '+safe(u.status)+'</span><button class=\"btn-main\" onclick=\"setUser('+u.id+',\\\''+next+'\\\')\">'+(next==='SUSPENDED'?'정지':'정지 해제')+'</button></div>';}).join('')||'<p class=\"muted\">검색 결과가 없습니다.</p>';controls('userPaging',userPage,Math.max(1,Math.ceil((d.total||0)/10)),function(i){userPage=i;loadUsers();});});}function setUser(id,status){fetch('/api/admin/users/'+id+'/status',{method:'PUT',headers:{'Content-Type':'application/x-www-form-urlencoded','X-CSRF-Token':csrf()},body:'status='+status}).then(function(r){if(r.ok){loadUsers();loadStats();}});}var postData=[],postPage=0;function renderPosts(){var q=document.getElementById('postQuery').value.toLowerCase(),a=q?postData.filter(function(p){return (p.title+' '+p.author).toLowerCase().indexOf(q)>=0;}):postData,pages=Math.max(1,Math.ceil(a.length/5));if(postPage>=pages)postPage=0;document.getElementById('adminPosts').innerHTML=a.slice(postPage*5,postPage*5+5).map(function(p){return '<div class=\"post-card admin-post-row\"><b>'+safe(p.title)+'</b><span>'+safe(p.author)+'</span><a class=\"btn-main\" href=\"/post/'+p.id+'\">보기</a><button class=\"btn-main\" onclick=\"hidePost('+p.id+')\">숨김</button></div>';}).join('')||'<p class=\"muted\">검색 결과가 없습니다.</p>';controls('postPaging',postPage,pages,function(i){postPage=i;renderPosts();});}function loadPosts(){fetch('/api/posts').then(function(r){return r.json();}).then(function(d){postData=d.posts||[];renderPosts();});}function hidePost(id){if(!confirm('이 게시글을 숨길까요?'))return;fetch('/api/admin/posts/'+id+'/hide',{method:'PUT',headers:{'X-CSRF-Token':csrf()}}).then(function(r){if(r.ok){loadPosts();loadStats();}});}var reportData=[],reportPage=0;function renderReports(){var q=document.getElementById('reportQuery').value.toLowerCase(),a=q?reportData.filter(function(x){return (x.type+' '+x.reason+' '+x.reporter).toLowerCase().indexOf(q)>=0;}):reportData,pages=Math.max(1,Math.ceil(a.length/5));if(reportPage>=pages)reportPage=0;document.getElementById('reports').innerHTML=a.slice(reportPage*5,reportPage*5+5).map(function(x){return '<div class=\"post-card admin-report-row\"><b>'+safe(x.type)+' #'+x.targetId+'</b><span>'+safe(x.reason)+' · '+safe(x.reporter)+' · '+safe(x.status)+'</span><button class=\"btn-main\" onclick=\"resolveReport('+x.id+',\\\'RESOLVED\\\')\">처리</button><button class=\"btn-main\" onclick=\"resolveReport('+x.id+',\\\'REJECTED\\\')\">반려</button></div>';}).join('')||'<p class=\"muted\">신고가 없습니다.</p>';controls('reportPaging',reportPage,pages,function(i){reportPage=i;renderReports();});}function loadReports(){fetch('/api/admin/reports').then(function(r){return r.json();}).then(function(d){reportData=d.reports||[];renderReports();});}function resolveReport(id,status){fetch('/api/admin/reports/'+id,{method:'PUT',headers:{'Content-Type':'application/x-www-form-urlencoded','X-CSRF-Token':csrf()},body:'status='+status}).then(function(r){if(r.ok){loadReports();loadStats();}});}document.getElementById('userSearch').onclick=function(){userPage=0;loadUsers();};document.getElementById('postSearch').onclick=function(){postPage=0;renderPosts();};document.getElementById('reportSearch').onclick=function(){reportPage=0;renderReports();};loadStats();loadUsers();loadPosts();loadReports();</script></body></html>";
    }
}
